const text = $input.first().json.output[0].content[0].text;

let prospects = [];

try {
  let cleaned = String(text).trim();

  // Remove markdown code fences if present
  cleaned = cleaned
    .replace(/^```json\s*/i, "")
    .replace(/^```\s*/i, "")
    .replace(/\s*```$/i, "")
    .trim();

  // Extract each JSON object individually
  const objects = [];
  let depth = 0;
  let start = -1;
  let inString = false;
  let escaped = false;

  for (let i = 0; i < cleaned.length; i++) {
    const char = cleaned[i];

    if (inString) {
      if (escaped) {
        escaped = false;
      } else if (char === "\\") {
        escaped = true;
      } else if (char === '"') {
        inString = false;
      }
      continue;
    }

    if (char === '"') {
      inString = true;
      continue;
    }

    if (char === "{") {
      if (depth === 0) {
        start = i;
      }
      depth++;
    }

    if (char === "}") {
      depth--;

      if (depth === 0 && start !== -1) {
        const jsonObject = cleaned.substring(start, i + 1);

        try {
          const parsed = JSON.parse(jsonObject);
          objects.push(parsed);
        } catch (e) {
          // Ignore invalid object and continue extracting others
        }

        start = -1;
      }
    }
  }

  prospects = objects;

  if (prospects.length === 0) {
    throw new Error("No valid JSON prospect objects found");
  }

} catch (error) {
  return [{
    json: {
      error: "Could not parse OpenAI output",
      parse_error: error.message,
      raw_output: text
    }
  }];
}

// Return each prospect as a separate n8n item
return prospects.map(prospect => ({
  json: {
    company_name: prospect.company_name || "",
    phone: prospect.phone || "",
    location: prospect.location || "",
    website: prospect.website || "",
    email: prospect.email || "",
    main_services: prospect.main_services || "",
    business_signals: prospect.business_signals || "",
    pain_point: prospect.pain_point || "",
    problem: prospect.problem || "",
    comparison_with_client_profile: prospect.comparison_with_client_profile || "",
    recommended_solution: prospect.recommended_solution || "",
    qualification_status: prospect.qualification_status || "",
    source_urls: Array.isArray(prospect.source_urls)
      ? prospect.source_urls
      : []
  }
}));

return $input.all().map(item => {
  const now = new Date();

  const data = {
    ...item.json,
    prospect_id: item.json.prospect_id || `PRO-${Math.random().toString(36).substring(2, 10).toUpperCase()}`,
    outreach_id: `OUT-${Math.random().toString(36).substring(2, 10).toUpperCase()}`,
    research_date: now.toISOString().split('T')[0],
    created_at: now.toISOString()
  };

  const emailText = data.email || "";
  const match = emailText.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/i);

  data.email = match ? match[0] : "";

  return {
    json: data
  };
});

const input = $input.first().json.output;

let text = String(input || "").trim();

// Remove markdown code fences
text = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .replace(/\\@/g, "@")
  .trim();

let leads;

// Try normal JSON first
try {
  leads = JSON.parse(text);
} catch (error) {

  // Handle multiple JSON objects returned without an array
  const matches = text.match(/\{[\s\S]*?\}(?=\s*\{|\s*$)/g);

  if (!matches || matches.length === 0) {
    return [{
      json: {
        error: "Could not parse AI output",
        parse_error: error.message,
        raw_output: text
      }
    }];
  }

  try {
    leads = matches.map(item => JSON.parse(item));
  } catch (parseError) {
    return [{
      json: {
        error: "Could not parse individual prospect objects",
        parse_error: parseError.message,
        raw_output: text
      }
    }];
  }
}

// Make sure we have an array
if (!Array.isArray(leads)) {
  leads = [leads];
}

// Current date and time
const now = new Date().toISOString();

// Create one n8n item per prospect
return leads.map(lead => ({
  json: {
    prospect_id: String(lead.prospect_id || ""),
    company_name: String(lead.company_name || ""),
    contact_name: String(lead.contact_name || ""),
    email: String(lead.email || ""),
    email_status: String(lead.email_status || ""),
    subject: String(lead.subject || ""),
    email_body: String(lead.email_body || ""),
    created_at: String(now),
    updated_at: String(now)
  }
}));

return $input.all().map(item => {
  const data = { ...item.json };

  const currentCount = parseInt(data.follow_up_count, 10);

  const nextCount = Number.isFinite(currentCount)
    ? currentCount + 1
    : 1;

  const now = new Date();

  data.follow_up_count = nextCount;
  data.sent_at = now.toISOString();
  data.follow_up_date = now.toISOString().split('T')[0];

  return {
    json: data
  };
});

const input = $json.output;

let text = "";

// Get the AI text from the OpenAI output structure
if (Array.isArray(input)) {
  const first = input[0];

  if (first?.content && Array.isArray(first.content)) {
    const textPart = first.content.find(
      item => item?.type === "output_text"
    );

    text = textPart?.text || "";
  }
}

// Fallback if output is already a string
if (!text && typeof input === "string") {
  text = input;
}

text = String(text).trim();

// Remove markdown code fences if present
text = text
  .replace(/^```json\s*/i, "")
  .replace(/^```\s*/i, "")
  .replace(/\s*```$/i, "")
  .trim();

let data;

try {
  data = JSON.parse(text);
} catch (error) {
  return [
    {
      json: {
        prospect_name: "",
        prospect_id: "",
        client_id: "",
        client_name: "",
        reply_content: "",
        conversation_complete: "",
        reply_intent: "",
        start_time: "",
        end_time: "",
        created_at: "",
        updated_at: "",
        parse_error: error.message,
        raw_output: text
      }
    }
  ];
}

// Return every required value as a separate string
return [
  {
    json: {
      prospect_name: String(data.prospect_name || ""),
      prospect_id: String(data.prospect_id || ""),
      client_id: String(data.client_id || ""),
      client_name: String(data.client_name || ""),
      reply_content: String(data.reply_content || ""),
      conversation_complete: String(data.conversation_complete || ""),
      reply_intent: String(data.reply_intent || ""),
      start_time: String(data.start_time || ""),
      end_time: String(data.end_time || ""),
      created_at: String(data.created_at || ""),
      updated_at: String(data.updated_at || "")
    }
  }
];

const text = $('Email_Replying_Agent1').first().json.output[0].content[0].text;

let data;

try {
  data = JSON.parse(text);
} catch (error) {
  throw new Error('Could not parse AI output as JSON: ' + error.message);
}

const replyIntent = String(data.reply_intent || '');

if (replyIntent !== 'book_appointment') {
  return [{
    json: {
      timeMin: '',
      timeMax: '',
      reply_intent: replyIntent,
      approval_status: 'interested'
    }
  }];
}

if (!data.start_time || !data.end_time) {
  throw new Error('start_time or end_time is missing from AI output');
}

return [{
  json: {
    timeMin: String(data.start_time),
    timeMax: String(data.end_time),
    reply_intent: replyIntent,
    approval_status: 'interested'
  }
}];
